// RelationalLexerInit initializes any static state used to implement RelationalLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewRelationalLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func RelationalLexerInit() {
	staticData := &RelationalLexerLexerStaticData
	staticData.once.Do(relationallexerLexerInit)
}

// NewRelationalLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewRelationalLexer(input antlr.CharStream) *RelationalLexer {
	RelationalLexerInit()
	l := new(RelationalLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &RelationalLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "RelationalLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

